import{_ as i,C as n,o as d,c as l,aj as r,G as s,j as a,a as o}from"./chunks/framework.BwH0p-pt.js";const y=JSON.parse(`{"title":"What's New in UnoPim 3.0","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/releases/index.md","filePath":"3.0/releases/index.md","lastUpdated":1785836850000}`),h={name:"3.0/releases/index.md"};function u(c,e,p,m,g,f){const t=n("ImagePopup");return d(),l("div",null,[e[0]||(e[0]=r('<h1 id="what-s-new-in-unopim-3-0" tabindex="-1">What&#39;s New in UnoPim 3.0 <a class="header-anchor" href="#what-s-new-in-unopim-3-0" aria-label="Permalink to &quot;What&#39;s New in UnoPim 3.0&quot;">​</a></h1><p>UnoPim 3.0 was released on July 31, 2026. It is the biggest release so far, and most of it is aimed squarely at the people who work in the catalog every day: Digital Product Passports for EU compliance, association types you define yourself, two-level product variants with inherited values, measurement attributes, powerful product grid filters with saved views, and a faster, modernized admin with dark mode.</p><p>This page walks through each major change and points you to the guide chapter where you can learn more.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>What&#39;s new</th></tr></thead><tbody><tr><td>Compliance</td><td><a href="./../passport/">Digital Product Passports</a> with ready-made EU templates</td></tr><tr><td>Catalog modeling</td><td><a href="./../associations/">Configurable associations</a>, <a href="./../products/variants.html">two-level variants</a>, <a href="./../measurements/">measurements</a></td></tr><tr><td>Daily work</td><td><a href="./../products/filters-and-views.html">Product grid filters and saved views</a>, a <a href="./../introduction/admin-essentials.html">modernized admin</a> with dark mode</td></tr><tr><td>Team access</td><td><a href="./../configuration/microsoft-sso.html">Microsoft sign-in</a>, per-user catalog locale and default channel</td></tr><tr><td>Connectivity</td><td><a href="./../configuration/webhooks.html">Multiple webhooks</a>, new <a href="./../data-transfer/import.html">import</a> and <a href="./../data-transfer/export.html">export</a> job types</td></tr><tr><td>Administration</td><td>A new <a href="./../configuration/system-settings.html">System Settings</a> hub, security and performance upgrades</td></tr></tbody></table><h2 id="stay-compliance-ready-with-digital-product-passports" tabindex="-1">Stay compliance-ready with Digital Product Passports <a class="header-anchor" href="#stay-compliance-ready-with-digital-product-passports" aria-label="Permalink to &quot;Stay compliance-ready with Digital Product Passports&quot;">​</a></h2><p>A Digital Product Passport is a public page for one of your products, reachable by scanning a QR code, that shows the data a regulator, recycler, or customer is entitled to see. UnoPim now builds these pages from the product data you already maintain — you design a passport template, bind it to a product family, and publish. Ready-made templates for the EU Battery Regulation and ESPR are included, and every publish is kept in a version history you can look back on.</p><p>Learn more in <a href="./../passport/">Digital Product Passport</a>.</p>',8)),s(t,{src:"/assets/3.0/images/releases/digital-product-passport.png",alt:"A published Digital Product Passport page with its QR code"}),e[1]||(e[1]=a("h2",{id:"model-any-product-relationship-with-configurable-associations",tabindex:"-1"},[o("Model any product relationship with configurable associations "),a("a",{class:"header-anchor",href:"#model-any-product-relationship-with-configurable-associations","aria-label":'Permalink to "Model any product relationship with configurable associations"'},"​")],-1)),e[2]||(e[2]=a("p",null,"Until now, products could only be linked as related, cross-sell, or up-sell. In 3.0 you create your own association types — spare parts, accessories, replacements, bundles, or whatever your business needs — each with its own label in every catalog language. You can even add extra fields to each link, such as a quantity or a note, and fill them per language. The new types appear in the product editor, in imports and exports, and in the product grid.",-1)),e[3]||(e[3]=a("p",null,[o("Learn more in "),a("a",{href:"./../associations/"},"Product Associations"),o(".")],-1)),s(t,{src:"/assets/3.0/images/releases/association-types.png",alt:"The Association Types settings page with custom types"}),e[4]||(e[4]=a("h2",{id:"enrich-once-with-two-level-product-variants",tabindex:"-1"},[o("Enrich once with two-level product variants "),a("a",{class:"header-anchor",href:"#enrich-once-with-two-level-product-variants","aria-label":'Permalink to "Enrich once with two-level product variants"'},"​")],-1)),e[5]||(e[5]=a("p",null,"Variant management grew up in this release. A product family can now define up to two variant levels — for example style, then color, then size — and child products inherit shared values from their parent automatically. You enrich the description once on the parent, and every variant carries it. Variant groups and a redesigned family editor make large variant trees easy to browse and maintain.",-1)),e[6]||(e[6]=a("p",null,[o("Learn more in "),a("a",{href:"./../products/variants.html"},"Product Variants"),o(".")],-1)),s(t,{src:"/assets/3.0/images/releases/variant-tree.png",alt:"A two-level variant tree with inherited values highlighted"}),e[7]||(e[7]=r('<h2 id="end-unit-confusion-with-measurements" tabindex="-1">End unit confusion with measurements <a class="header-anchor" href="#end-unit-confusion-with-measurements" aria-label="Permalink to &quot;End unit confusion with measurements&quot;">​</a></h2><p>Sell in inches, store in centimeters, and export in whatever unit your channel demands. Measurements are now a first-class part of the catalog: you define measurement families with units and automatic conversions, set the precision you want, and use measurement attributes on your products like any other attribute.</p><p>Learn more in <a href="./../measurements/">Measurements</a>.</p><h2 id="find-products-faster-with-filters-and-saved-views" tabindex="-1">Find products faster with filters and saved views <a class="header-anchor" href="#find-products-faster-with-filters-and-saved-views" aria-label="Permalink to &quot;Find products faster with filters and saved views&quot;">​</a></h2><p>The product grid now filters by category, completeness, creation and update dates, product properties, and any attribute value — each with operators that fit the attribute type. Once you have the columns and filters you like, save the combination as a view and return to it with one click. Your &quot;German descriptions missing&quot; view is always one click away.</p><p>Learn more in <a href="./../products/filters-and-views.html">Filters &amp; Saved Views</a>.</p>',6)),s(t,{src:"/assets/3.0/images/releases/filters-saved-views.png",alt:"The product grid with attribute filters applied and a saved view selected"}),e[8]||(e[8]=r('<h2 id="work-faster-in-a-modernized-admin" tabindex="-1">Work faster in a modernized admin <a class="header-anchor" href="#work-faster-in-a-modernized-admin" aria-label="Permalink to &quot;Work faster in a modernized admin&quot;">​</a></h2><p>The whole admin was rebuilt for speed and comfort:</p><ul><li><strong>Dark mode</strong> — choose light or dark, or let UnoPim follow your browser.</li><li><strong>No more full-page reloads</strong> — moving between pages and saving changes happens instantly, and your browser history still works.</li><li><strong>A Save/Discard bar</strong> — it appears only when something changed, tells you which sections are unsaved, and warns you before you navigate away.</li><li><strong>Quick-create everywhere</strong> — create attributes, groups, families, category fields, and association types from a small modal without leaving your current page.</li><li><strong>A category tree browser</strong> — browse, search, and reorganize large category trees, with lazy loading for big branches.</li></ul><p>Learn more in <a href="./../introduction/admin-essentials.html">Admin Essentials</a>.</p>',4)),s(t,{src:"/assets/3.0/images/releases/admin-dark-mode.png",alt:"The UnoPim admin dashboard in dark mode"}),e[9]||(e[9]=r('<h2 id="sign-in-with-microsoft" tabindex="-1">Sign in with Microsoft <a class="header-anchor" href="#sign-in-with-microsoft" aria-label="Permalink to &quot;Sign in with Microsoft&quot;">​</a></h2><p>Teams that live in Microsoft 365 can now sign in to UnoPim with their Microsoft work accounts. An administrator connects the organization once; from then on, colleagues use the <strong>Sign in with Microsoft</strong> button and never manage a separate UnoPim password. Access stays restricted to the tenants you allow.</p><p>Learn more in <a href="./../configuration/microsoft-sso.html">Microsoft SSO</a>.</p><h2 id="keep-every-system-in-sync-with-multiple-webhooks" tabindex="-1">Keep every system in sync with multiple webhooks <a class="header-anchor" href="#keep-every-system-in-sync-with-multiple-webhooks" aria-label="Permalink to &quot;Keep every system in sync with multiple webhooks&quot;">​</a></h2><p>One webhook was never enough. You can now register as many webhook endpoints as you need — one for your ERP, one for your shop, one for a marketplace — each subscribed to exactly the events it cares about. Every delivery is signed and recorded in its own log, so you can see what was sent, when, and whether it arrived.</p><p>Learn more in <a href="./../configuration/webhooks.html">Webhooks</a>.</p><h2 id="move-more-data-with-import-and-export" tabindex="-1">Move more data with import and export <a class="header-anchor" href="#move-more-data-with-import-and-export" aria-label="Permalink to &quot;Move more data with import and export&quot;">​</a></h2><p>Data transfer covers far more of the catalog now. New job types let you import and export attributes, attribute groups, attribute families, attribute options, category fields, association links, locales, channels, currencies, roles, and users — with sample files for each. Product exports gain rich filters (status, completeness, categories, date ranges such as &quot;since the last export&quot;, and attribute-value conditions), and a <strong>quick export</strong> sends exactly the products you selected in the grid.</p><p>Learn more in <a href="./../data-transfer/import.html">Import</a> and <a href="./../data-transfer/export.html">Export</a>.</p>',9)),s(t,{src:"/assets/3.0/images/releases/export-filters.png",alt:"Product export job with filter conditions configured"}),e[10]||(e[10]=r('<h2 id="make-unopim-yours-per-user-settings-and-the-system-settings-hub" tabindex="-1">Make UnoPim yours: per-user settings and the System Settings hub <a class="header-anchor" href="#make-unopim-yours-per-user-settings-and-the-system-settings-hub" aria-label="Permalink to &quot;Make UnoPim yours: per-user settings and the System Settings hub&quot;">​</a></h2><p>Each user can now pick a personal catalog locale and a default channel, and UnoPim uses them consistently — in product editing, in account settings, and in background jobs. Administration also has a new home: the <strong>System Settings</strong> hub gathers appearance (including your own logo and favicon), email, sign-in, measurements, passports, and more into one searchable page, alongside a System Information page that shows the health of your installation at a glance.</p><p>Learn more in <a href="./../settings/users.html">Users</a> and <a href="./../configuration/system-settings.html">System Settings</a>.</p><h2 id="safer-and-faster-out-of-the-box" tabindex="-1">Safer and faster, out of the box <a class="header-anchor" href="#safer-and-faster-out-of-the-box" aria-label="Permalink to &quot;Safer and faster, out of the box&quot;">​</a></h2><p>Security and speed both received their largest upgrade yet. Every installation now uses its own unique signing keys, stored content is sanitized against script injection, and passwords follow a central policy across the whole application. At the same time, the platform was tuned for very large catalogs: exports, mass actions, and product screens stay responsive even with millions of products, and heavy operations run in the background instead of making you wait.</p><div class="tip custom-block"><p class="custom-block-title">For your integration team</p><p>The REST API grew substantially in 3.0: full management of catalog structure (attributes, families, locales, channels, currencies), media endpoints, passport publishing, and delta synchronization that fetches only what changed. Point your developers to the developer documentation for details.</p></div><h2 id="before-you-upgrade" tabindex="-1">Before you upgrade <a class="header-anchor" href="#before-you-upgrade" aria-label="Permalink to &quot;Before you upgrade&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">UnoPim 3.0 is a major release</p><p>Existing API connections must authenticate again after the upgrade, and a few admin page addresses changed. Review the upgrade guide shipped with the release and test the upgrade on a copy of your installation before updating production.</p></div><p>Enjoy UnoPim 3.0 — and if something in this guide does not answer your question, the community on GitHub is happy to help.</p>',9))])}const b=i(h,[["render",u]]);export{y as __pageData,b as default};
